import{_ as r}from"./chunks/01-editor-overview.B6DfPzWc.js";import{_ as o,a as s,b as n,c as g,d as e,e as d,f as a,g as i}from"./chunks/12-editor-render.C4Mg-YM8.js";import{_ as l,o as c,c as p,a2 as h}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"المحرر","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/editor.md","filePath":"ar/guide/editor.md"}'),m={name:"ar/guide/editor.md"};function u(_,t,f,b,C,S){return c(),p("div",null,[...t[0]||(t[0]=[h('<h1 id="المحرر" tabindex="-1">المحرر <a class="header-anchor" href="#المحرر" aria-label="Permalink to &quot;المحرر&quot;">​</a></h1><p>المحرر هو المكان الذي تصمم فيه الحلقة. يعمل مثل برنامج تصميم مبني فوق خط زمني للفيديو، لكنه مصمَّم لمهمة واحدة: أن تضع مكوّنات متحركة على الإطار الحقيقي بمقاس 1080×1920 وتضبط توقيتها على الكلمات التي تنطقها.</p><p>افتحه من لوحة التحكم بزر <strong>Open editor</strong>، أو شغّل <code>reelforge edit &lt;id&gt;</code>. يفتحه الأمر <code>reelforge cue &lt;id&gt;</code> في وضع Cues، والأمر <code>reelforge dev &lt;id&gt;</code> في وضع Review.</p><p><img src="'+r+'" alt="المحرر"></p><table tabindex="0"><thead><tr><th>المنطقة</th><th>ما تحتويه</th></tr></thead><tbody><tr><td><strong>الشريط العلوي</strong></td><td>الأوضاع (Edit وCues وReview)، والتراجع والإعادة، والتشغيل والسرعة، والحالة، والفحوص، والبحث، و<strong>Render</strong></td></tr><tr><td><strong>اللوحة اليسرى</strong></td><td><strong>Layers</strong> (المشاهد ثم العناصر)، و<strong>Insert</strong> (كل المكوّنات)، و<strong>Script</strong> (أسطرك)</td></tr><tr><td><strong>مساحة العمل (Canvas)</strong></td><td>الإطار الحقيقي، مرسوماً بالمحرك نفسه الذي يرسم الفيديو النهائي، ومتزامناً مع صوتك</td></tr><tr><td><strong>اللوحة اليمنى</strong></td><td><strong>لوحة الخصائص</strong> (Inspector) لما حددته (أو إعدادات الحلقة عند عدم تحديد شيء)</td></tr><tr><td><strong>الخط الزمني</strong></td><td>الفصول والمشاهد وأسطر النص ومسار لكل طبقة، وموجة صوتك مع المؤثرات</td></tr></tbody></table><p>يُكتب كل تعديل في <code>episode.yaml</code> فوراً مع الحفاظ على تعليقاتك وتنسيقك. ويمكن التراجع عن أي تعديل (‏**⌘Z** أو <strong>Ctrl+Z</strong>)، بما في ذلك تعديلات الـ cues. يمكنك إبقاء <code>episode.yaml</code> مفتوحاً في محرر نصوص في الوقت نفسه، وتظهر التعديلات التي تجريها هناك في المحرر بمجرد الحفظ.</p><h2 id="مساحة-العمل-canvas" tabindex="-1">مساحة العمل (Canvas) <a class="header-anchor" href="#مساحة-العمل-canvas" aria-label="Permalink to &quot;مساحة العمل (Canvas)&quot;">​</a></h2><ul><li><strong>انقر</strong> على عنصر لتحديده، ويحدد <strong>Alt مع النقر</strong> العنصر الذي تحته. ويظهر إطار حول العنصر عند المرور فوقه.</li><li><strong>اسحب</strong> للتحريك. تلتصق أدلة المحاذاة الذكية بمركز الإطار ومنطقة المشهد والعناصر الأخرى. اضغط <strong>Shift</strong> للتحريك في خط مستقيم، أو <strong>Alt</strong> لإيقاف الالتصاق.</li><li><strong>اسحب مقبضاً</strong> لتغيير الحجم. اضغط <strong>Shift</strong> للحفاظ على النسب، أو <strong>Alt</strong> لتغيير الحجم من المركز.</li><li>استخدم <strong>مفاتيح الأسهم</strong> للتحريك بمقدار 1 px (و<strong>Shift</strong> بمقدار 10 px).</li><li><strong>انقر مرتين</strong> على <code>title</code> أو <code>label</code> أو <code>chip</code> أو <code>stamp</code> أو <code>quote</code> أو <code>node</code> أو بطاقة الختام <strong>لتعديل نصه في مكانه</strong>. اضغط <strong>Enter</strong> للحفظ أو <strong>Esc</strong> للإلغاء.</li><li><strong>اسحب مكوّناً</strong> من <strong>Insert</strong> إلى مساحة العمل لإضافته في ذلك الموضع.</li><li><strong>كبّر</strong> بـ <strong>⌘/Ctrl مع عجلة الفأرة</strong>، أو <strong>Shift+1</strong> (ملاءمة)، أو <strong>Shift+2</strong> (التحديد)، أو <strong>Shift+0</strong> ‏(100%). <strong>تنقّل</strong> بالعجلة، أو بالضغط المستمر على <strong>Space</strong>، أو بأداة <strong>H</strong>.</li><li>يبدّل شريط الأدوات العائم عرض <strong>المناطق الآمنة</strong> (‏<strong>Z</strong>، حيث ترسم TikTok وReels وShorts أزرارها)، و<strong>أدلة المسرح والترجمة النصية</strong> (‏<strong>B</strong>)، و<strong>حدود العناصر</strong> (‏<strong>E</strong>).</li></ul><p><img src="'+o+'" alt="التحريك مع أدلة المحاذاة"></p><h2 id="الطبقات-والإدراج-والنص" tabindex="-1">الطبقات والإدراج والنص <a class="header-anchor" href="#الطبقات-والإدراج-والنص" aria-label="Permalink to &quot;الطبقات والإدراج والنص&quot;">​</a></h2><p>تعرض <strong>Layers</strong> كل مشهد وعناصره، وما في أعلى القائمة يُرسم فوق غيره. انقر للتحديد (ينتقل مؤشر التشغيل إلى لحظة يكون فيها العنصر ظاهراً)، و<strong>اسحب</strong> لإعادة الترتيب، و<strong>انقر مرتين</strong> لإعادة التسمية. وتحدّث إعادة التسمية أيضاً كل الأسهم التي تشير إلى العنصر. وتميّز نقطة خضراء ما يظهر على الشاشة عند مؤشر التشغيل.</p><p>تعرض <strong>Insert</strong> المكوّنات الـ 62 كلها في مجموعات: <strong>Text</strong> و<strong>Diagrams</strong> و<strong>Data</strong> و<strong>Charts</strong> و<strong>Process &amp; structure</strong> و<strong>Places &amp; movement</strong> و<strong>Time</strong> و<strong>People &amp; messaging</strong> و<strong>Media &amp; text</strong> و<strong>Health &amp; data</strong> و<strong>Code &amp; devices</strong> و<strong>Effects &amp; endings</strong>. <strong>انقر</strong> على مكوّن لإضافته إلى المشهد الحالي عند مؤشر التشغيل، أو اسحبه إلى مساحة العمل. وتبدأ العناصر الجديدة بمحتوى افتراضي مناسب يمكنك تغييره فوراً.</p><p><img src="'+s+'" alt="لوحة الإدراج"></p><p>تحتوي <strong>Script</strong> على نصك، جملة منطوقة في كل سطر. عدّل السطر في مكانه، واستخدم أزراره للإضافة والحذف وإعادة الترتيب. الأسطر العربية والإنجليزية والمختلطة كلها مدعومة، ويُكتشف الاتجاه تلقائياً.</p><h2 id="لوحة-الخصائص-inspector" tabindex="-1">لوحة الخصائص (Inspector) <a class="header-anchor" href="#لوحة-الخصائص-inspector" aria-label="Permalink to &quot;لوحة الخصائص (Inspector)&quot;">​</a></h2><p>تعدّل لوحة الخصائص <strong>كل خاصية</strong> فيما حددته:</p><ul><li><strong>الموضع والحجم</strong> (X وY وW وH)، وأزرار المحاذاة، والطبقة وترتيب التراكب.</li><li><strong>الحركة والتوقيت</strong>: متى يدخل العنصر، والحركة، ومنحنى تسارعها (ease) ومدتها، وخروج اختياري. يشغّل الزر <strong>Preview animation</strong> تلك اللحظة وحدها مرة واحدة، وعند اختيار حركة أو منحنى تسارع جديد تُعرض معاينته تلقائياً. ويضبط الزر <strong>target</strong> الزمن على موضع مؤشر التشغيل، فيكتب زمناً مرتبطاً بكلمة مثل <code>l3:&#39;bucket&#39;</code> كلما كان المؤشر على كلمة، وبذلك يبقى العنصر على تلك الكلمة حتى بعد إعادة التسجيل.</li><li><strong>الخصائص</strong>: كل خيارات المكوّن، مولّدة من الـ schema الخاص به: حقول نصية، وأرقام (اسحب المقبض المنقّط لتغييرها)، ومفاتيح تشغيل وإيقاف، وقوائم، وألوان (ألوان الثيم أو أي لون)، وأزمنة، وقوائم يمكنك الإضافة إليها وإعادة ترتيبها والحذف منها.</li><li><strong>Effects</strong> (الاهتزاز والوميض والتشويش والنبض والارتداد) و<strong>States</strong> (تغيير خصائص عند زمن معين، مثل عقدة يتحول لونها إلى الأحمر).</li><li><strong>Sound</strong>: تشغيل المؤثرات الصوتية التلقائية أو إيقافها.</li><li><strong>YAML (advanced)</strong>: نص YAML الدقيق للعنصر. يمكن تعديل أي شيء تدعمه الصيغة من هنا.</li></ul><p>عند تحديد <strong>مشهد</strong>، تعدّل لوحة الخصائص بدايته ونهايته، والانتقال، وحركة الكاميرا (مع <strong>Preview transition</strong>)، والمنطقة (المسرح أو الإطار كاملاً)، وتوهج الخلفية، والتخطيط التلقائي. وعند تحديد <strong>سطر نص</strong>، تعدّل النص ونص الترجمة النصية وفواصل الأسطر والـ cue، وتعرض كل كلماته (انقر على كلمة للانتقال إليها). وعند <strong>عدم تحديد شيء</strong>، تعدّل الحلقة نفسها: العنوان والسلسلة والمنصة والثيم واللغة ونصوص النشر والصوت والفصول.</p><p><img src="'+n+'" alt="سطر نص في لوحة الخصائص"></p><h2 id="الخط-الزمني" tabindex="-1">الخط الزمني <a class="header-anchor" href="#الخط-الزمني" aria-label="Permalink to &quot;الخط الزمني&quot;">​</a></h2><p><img src="'+g+'" alt="إعادة توقيت مقطع على الخط الزمني"></p><ul><li><strong>انقر على المسطرة أو اسحبها</strong> لتحريك مؤشر التشغيل. تظهر الفصول على المسطرة.</li><li><strong>المشاهد</strong>: اسحب بداية المشهد لتحريكها.</li><li><strong>النص</strong>: كل سطر مقطع. اسحبه لتغيير الـ cue الخاص به، وتتحرك علامات كلماته معه.</li><li><strong>مسارات الطبقات</strong>: كل عنصر مقطع يمتد من دخوله حتى خروجه. <ul><li>اسحب <strong>جسم المقطع</strong> لإعادة توقيته.</li><li>اسحب <strong>الطرف الأيسر</strong> لتغيير زمن الدخول.</li><li>اسحب <strong>الطرف الأيمن</strong> لتحديد زمن الخروج. سحبه إلى نهاية المشهد يلغي الخروج.</li><li>تشير المعيّنات إلى المؤثرات (برتقالية) وتغييرات الحالة (زرقاء).</li></ul></li><li>تلتصق المقاطع بـ <strong>الكلمات</strong> وبدايات الأسطر والمشاهد ومؤشر التشغيل. تعرض الشارة تعبير الزمن الذي سيُحفظ. اضغط <strong>Alt</strong> للسحب بحرية، أو <strong>S</strong> لإيقاف الالتصاق.</li><li>يضبط <strong>I</strong> و<strong>O</strong> نقطتي دخول العنصر المحدد وخروجه عند مؤشر التشغيل.</li><li><strong>كبّر</strong> بـ <strong>= / −</strong> أو شريط التمرير أو <strong>⌘/Ctrl مع العجلة</strong>. ويعرض <strong>\\</strong> الحلقة كاملة.</li></ul><h2 id="ابحث-عن-كل-شيء-⌘k-أو-ctrl-k" tabindex="-1">ابحث عن كل شيء: ⌘K أو Ctrl+K <a class="header-anchor" href="#ابحث-عن-كل-شيء-⌘k-أو-ctrl-k" aria-label="Permalink to &quot;ابحث عن كل شيء: ⌘K أو Ctrl+K&quot;">​</a></h2><p>تعثر لوحة الأوامر على كل أمر ومكوّن ومشهد وعنصر وسطر نص. اكتب بضعة أحرف واضغط <strong>Enter</strong>. جرّب <code>insert counter</code> أو <code>go to scene trap</code> أو <code>safe zones</code>.</p><p><img src="'+e+'" alt="لوحة الأوامر"></p><p>انقر بالزر الأيمن على مساحة العمل أو على طبقة أو مقطع لتصل إلى أكثر الإجراءات استخداماً. واضغط <strong>?</strong> لعرض كل الاختصارات.</p><p><img src="'+d+'" alt="اختصارات لوحة المفاتيح"></p><h2 id="وضع-المراجعة-review" tabindex="-1">وضع المراجعة (Review) <a class="header-anchor" href="#وضع-المراجعة-review" aria-label="Permalink to &quot;وضع المراجعة (Review)&quot;">​</a></h2><p>يعرض وضع <strong>Review</strong> (‏<strong>Alt+3</strong>، أو النقر على مؤشر الفحوص في الشريط العلوي) كل مشكلة تجدها الفحوص: الـ schema، والتوقيت، والتداخل، والمناطق الآمنة، وتجاوز النص لصندوقه مقيساً في متصفح حقيقي، وطول الترجمة النصية. لكل مشكلة تلميح لإصلاحها، وبالنقر عليها تنتقل إلى زمنها ويُحدَّد العنصر.</p><p><img src="'+a+'" alt="وضع المراجعة"></p><p>إذا احتوى <code>episode.yaml</code> خطأً في البنية (syntax) (بعد تعديله يدوياً مثلاً)، يظهر شريط يعرض السطر والرسالة، ويواصل المحرر عرض آخر نسخة سليمة.</p><h2 id="التصدير-من-المحرر" tabindex="-1">التصدير من المحرر <a class="header-anchor" href="#التصدير-من-المحرر" aria-label="Permalink to &quot;التصدير من المحرر&quot;">​</a></h2><p>انقر <strong>Render</strong> (‏**⌘/Ctrl+Enter**) واختر المنصة، وحجم ملف النشر، والمؤثرات الصوتية، والوضع الصامت (حين لا يوجد تسجيل بعد)، ومسودة سريعة. يمكنك مواصلة التحرير أثناء التصدير، ويظهر التقدم في الشريط العلوي. عند الانتهاء تُفتح الفيديوهات في مشغّل مع روابط التنزيل.</p><p><img src="'+i+'" alt="التصدير"></p><h2 id="الاختصارات-في-لمحة" tabindex="-1">الاختصارات في لمحة <a class="header-anchor" href="#الاختصارات-في-لمحة" aria-label="Permalink to &quot;الاختصارات في لمحة&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المفاتيح</th><th>الإجراء</th></tr></thead><tbody><tr><td><strong>Space</strong> / <strong>K</strong></td><td>تشغيل / إيقاف مؤقت</td></tr><tr><td><strong>J</strong> / <strong>L</strong>، <strong>,</strong> / <strong>.</strong></td><td>−1 ث / +1 ث، الإطار السابق / التالي</td></tr><tr><td><strong>Home</strong> / <strong>End</strong></td><td>البداية / النهاية</td></tr><tr><td><strong>1 2 3</strong></td><td>السرعة 0.5× و0.75× و1×</td></tr><tr><td><strong>⌘/Ctrl+Z</strong>، <strong>⌘/Ctrl+Shift+Z</strong></td><td>تراجع، إعادة</td></tr><tr><td><strong>⌘/Ctrl+D</strong>، <strong>⌘/Ctrl+C</strong>، <strong>⌘/Ctrl+V</strong></td><td>تكرار، نسخ، لصق عند مؤشر التشغيل</td></tr><tr><td><strong>Delete</strong></td><td>حذف التحديد</td></tr><tr><td><strong>⌘/Ctrl+]</strong>، <strong>⌘/Ctrl+[</strong></td><td>تقديم طبقة للأمام، إرجاع طبقة للخلف</td></tr><tr><td><strong>I</strong> / <strong>O</strong></td><td>الدخول / الخروج عند مؤشر التشغيل</td></tr><tr><td><strong>A</strong></td><td>إدراج مكوّن</td></tr><tr><td><strong>N</strong></td><td>إضافة مشهد عند مؤشر التشغيل</td></tr><tr><td><strong>Tab</strong> / <strong>Shift+Tab</strong></td><td>العنصر التالي / السابق</td></tr><tr><td><strong>Z</strong>، <strong>B</strong>، <strong>E</strong></td><td>المناطق الآمنة، أدلة المسرح، حدود العناصر</td></tr><tr><td><strong>S</strong></td><td>الالتصاق</td></tr><tr><td><strong>Alt+1 / 2 / 3</strong></td><td>Edit / Cues / Review</td></tr><tr><td><strong>⌘/Ctrl+K</strong></td><td>لوحة الأوامر</td></tr><tr><td><strong>?</strong></td><td>كل الاختصارات</td></tr></tbody></table>',36)])])}const P=l(m,[["render",u]]);export{k as __pageData,P as default};
